#include <cassert>
#include <cstring>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include "libzippp.h"

using namespace libzippp;

static int failures = 0;
#define CHECK(cond) do { if (!(cond)) { std::cerr << "FAIL line " << __LINE__ << ": " #cond << std::endl; ++failures; } } while(0)

// streambuf whose overflow sets failbit indirectly: we make write fail by
// returning 0 from xsputn
struct FailingBuf : std::streambuf {
    std::streamsize xsputn(const char*, std::streamsize) override { return 0; }
};

// streambuf that throws a non-ios exception during write
struct ThrowingBuf : std::streambuf {
    std::streamsize xsputn(const char*, std::streamsize) override {
        throw std::runtime_error("custom sink error");
    }
};

int main() {
    // build an archive in memory: one normal entry, one empty entry
    ZipArchive za("test008.zip");
    za.open(ZipArchive::Write);
    std::string content;
    for (int i = 0; i < 100000; ++i) content += "abcdefgh"; // 800KB > default chunk? use small chunks in tests
    content.push_back('\0'); // embedded zero byte must round-trip
    content += "tail";
    za.addData("big.txt", content.data(), content.size());
    za.addData("empty.txt", "", 0);
    za.close();

    za.open(ZipArchive::ReadOnly);
    ZipEntry big = za.getEntry("big.txt");
    ZipEntry empty = za.getEntry("empty.txt");
    CHECK(!big.isNull() && !empty.isNull());

    // 1. normal read via ostream round-trips content incl. zero bytes
    {
        std::ostringstream oss;
        int r = za.readEntry(big, oss, ZipArchive::Current, 4096);
        CHECK(r == LIBZIPPP_OK);
        CHECK(oss.str().size() == content.size());
        CHECK(oss.str() == content);
    }

    // 2. stream whose write fails (failbit set, no exceptions) -> OWRITE_FAILURE, state preserved
    {
        FailingBuf fb;
        std::ostream os(&fb);
        int r = za.readEntry(big, os, ZipArchive::Current, 4096);
        CHECK(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        CHECK(!os.good()); // failure state left as-is
        CHECK(os.exceptions() == std::ios::goodbit); // mask untouched
    }

    // 3. stream with exceptions enabled -> ios_base::failure converted to OWRITE_FAILURE
    {
        FailingBuf fb;
        std::ostream os(&fb);
        os.exceptions(std::ios::failbit | std::ios::badbit);
        int r = za.readEntry(big, os, ZipArchive::Current, 4096);
        CHECK(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        CHECK(os.exceptions() == (std::ios::failbit | std::ios::badbit)); // mask preserved
    }

    // 4. stream throwing a non-ios exception -> propagates unchanged
    {
        ThrowingBuf tb;
        std::ostream os(&tb);
        bool got = false;
        try {
            za.readEntry(big, os, ZipArchive::Current, 4096);
        } catch (const std::runtime_error& e) {
            got = true;
            CHECK(std::string(e.what()) == "custom sink error");
        }
        CHECK(got);
    }

    // 5. callback returning false -> OWRITE_FAILURE, not invoked again
    {
        int calls = 0;
        int r = za.readEntry(big, [&calls](const void*, libzippp_uint64) { ++calls; return false; }, ZipArchive::Current, 4096);
        CHECK(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        CHECK(calls == 1);
    }

    // 6. callback throwing std::ios_base::failure -> propagates as-is (NOT converted)
    {
        bool got = false;
        try {
            za.readEntry(big, [](const void*, libzippp_uint64) -> bool {
                throw std::ios_base::failure("receiver failed");
            }, ZipArchive::Current, 4096);
        } catch (const std::ios_base::failure& e) {
            got = true;
            CHECK(std::string(e.what()).find("receiver failed") != std::string::npos);
        }
        CHECK(got);
    }

    // 7. callback throwing custom exception -> propagates with type/payload intact
    {
        struct MyEx { int code; };
        bool got = false;
        try {
            za.readEntry(big, [](const void*, libzippp_uint64) -> bool { throw MyEx{42}; }, ZipArchive::Current, 4096);
        } catch (const MyEx& e) {
            got = true;
            CHECK(e.code == 42);
        }
        CHECK(got);
    }

    // 8. empty entry: zero-length delivery returning false -> OWRITE_FAILURE
    {
        int calls = 0;
        int r = za.readEntry(empty, [&calls](const void*, libzippp_uint64 n) { ++calls; CHECK(n == 0); return false; });
        CHECK(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        CHECK(calls == 1);
    }

    // 9. empty entry: callback throwing -> propagates
    {
        bool got = false;
        try {
            za.readEntry(empty, [](const void*, libzippp_uint64) -> bool { throw std::runtime_error("empty boom"); });
        } catch (const std::runtime_error& e) {
            got = true;
            CHECK(std::string(e.what()) == "empty boom");
        }
        CHECK(got);
    }

    // 10. empty entry: ostream that fails on the zero-length write -> OWRITE_FAILURE
    {
        FailingBuf fb;
        std::ostream os(&fb);
        int r = za.readEntry(empty, os);
        CHECK(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
    }

    // 11. after failures, archive/entry still usable: full re-read works
    {
        std::ostringstream oss;
        int r = big.readContent(oss);
        CHECK(r == LIBZIPPP_OK);
        CHECK(oss.str() == content);
    }

    // 12. repeated failing reads don't wedge the archive (leak check via valgrind separately)
    {
        for (int i = 0; i < 50; ++i) {
            try {
                za.readEntry(big, [](const void*, libzippp_uint64) -> bool { throw std::runtime_error("x"); }, ZipArchive::Current, 4096);
                CHECK(false);
            } catch (const std::runtime_error&) {}
        }
        std::ostringstream oss;
        CHECK(za.readEntry(big, oss, ZipArchive::Current, 4096) == LIBZIPPP_OK);
        CHECK(oss.str() == content);
    }

    za.close();

    // 13. writable archive still modifiable after failed reads; Current vs Original
    {
        ZipArchive zw("test008.zip");
        zw.open(ZipArchive::Write);
        ZipEntry e = zw.getEntry("big.txt");
        std::string repl = "replacement";
        zw.addData("big.txt", repl.data(), repl.size()); // pending replacement
        // failed read of Original
        try {
            zw.readEntry(e, [](const void*, libzippp_uint64) -> bool { throw std::runtime_error("y"); }, ZipArchive::Original, 4096);
            CHECK(false);
        } catch (const std::runtime_error&) {}
        // Original still readable fully
        std::ostringstream oss1;
        CHECK(zw.readEntry(e, oss1, ZipArchive::Original, 4096) == LIBZIPPP_OK);
        CHECK(oss1.str() == content);
        // Current gives the pending replacement
        std::ostringstream oss2;
        CHECK(zw.readEntry(e, oss2, ZipArchive::Current, 4096) == LIBZIPPP_OK);
        CHECK(oss2.str() == repl);
        zw.close();
    }

    // 14. ZipEntry::readContent with failing stream
    {
        za.open(ZipArchive::ReadOnly);
        ZipEntry e2 = za.getEntry("big.txt");
        FailingBuf fb;
        std::ostream os(&fb);
        CHECK(e2.readContent(os) == LIBZIPPP_ERROR_OWRITE_FAILURE);
        za.close();
    }

    if (failures == 0) std::cout << "ALL TESTS PASSED" << std::endl;
    return failures ? 1 : 0;
}

